import json
from pathlib import Path
from datetime import datetime, timezone
ROOT = Path('.').resolve()
ART = ROOT / 'artifacts'

def load(name):
    p = ART / name
    if not p.exists():
        return None
    try:
        return json.loads(p.read_text(encoding='utf-8'))
    except Exception:
        return None

ps = load('scoreboard_ss_pipeline_scripted.json') or {}
ds = load('scoreboard_ss_direct.json') or {}
ls = load('scoreboard_ss_ledger.json') or {}

def first_result(sb):
    rows = sb.get('results') or []
    return rows[0] if rows else {}

pr = first_result(ps)
dr = ds.get('results') or []
lr = first_result(ls)

fixtures = {}
for r in dr:
    fixtures[str(r.get('fixture') or 'x')] = {
        'elapsed_s': r.get('elapsed_s'),
        'n_steps': r.get('n_steps'),
        'ok': r.get('ok'),
    }
elapsed_list = [float(r.get('elapsed_s') or 0) for r in dr if r.get('elapsed_s') is not None]
mean_e = round(sum(elapsed_list)/len(elapsed_list), 3) if elapsed_list else None
max_e = round(max(elapsed_list), 3) if elapsed_list else None

scripted_s = float(pr.get('elapsed_s') or 0) or None
live_s = float(lr.get('elapsed_s') or 0) or None
ratio = round(live_s / scripted_s, 1) if scripted_s and live_s else None

bench = {
  'generated_at': datetime.now(timezone.utc).isoformat(),
  'source': 'scoreboard_ss_* measured runs',
  'hardware': {
    'gpu': 'GTX 1650 4GB',
    'ram_gb': 12,
    'primary_model': 'qwen3.5:4b',
    'constraint': 'host <=4B only',
  },
  'scripted_baselines': {
    'pipeline_ledger': {
      'arm': 'pipeline',
      'mode': 'scripted',
      'fixture': 'ledger',
      'ok': pr.get('ok'),
      'score': pr.get('score'),
      'elapsed_s': pr.get('elapsed_s'),
      'n_steps': pr.get('n_steps'),
      'strategy': pr.get('strategy'),
      'scoreboard': 'artifacts/scoreboard_ss_pipeline_scripted.json',
    },
    'direct_hard_pack': {
      'arm': 'direct',
      'mode': 'scripted',
      'tier': 'hard',
      'passed': (ds.get('summary') or {}).get('passed'),
      'total': (ds.get('summary') or {}).get('total'),
      'fixtures': fixtures,
      'mean_elapsed_s': mean_e,
      'max_elapsed_s': max_e,
      'scoreboard': 'artifacts/scoreboard_ss_direct.json',
    },
  },
  'live_contrast': {
    'pipeline_ledger_live': {
      'arm': 'pipeline',
      'mode': 'live',
      'fixture': 'ledger',
      'ok': lr.get('ok'),
      'score': lr.get('score'),
      'elapsed_s': lr.get('elapsed_s'),
      'reason': (lr.get('stages') or [{}])[-1].get('detail') if lr else None,
      'model': lr.get('model'),
      'honest_tool_path': lr.get('honest_tool_path'),
      'scoreboard': 'artifacts/scoreboard_ss_ledger.json',
    },
  },
  'speedup': {
    'scripted_vs_live_ledger': {
      'scripted_s': scripted_s,
      'live_s': live_s,
      'ratio': ratio,
      'note': 'scripted vs live same fixture',
    },
    'direct_hard_mean_s': mean_e,
    'implication': 'FAST-first steady path yields far more useful jobs/hour than live-ledger spam',
  },
  'host_policy': {
    'live_skip_ticks': 12,
    'steady_order': ['pipeline_scripted', 'direct_hard', 'tool_runtime', 'train_gates', 'archive', 'pref_refresh', 'pipeline_ledger_live'],
    'git_report': 'lightweight for FAST/continue_on_fail',
    'training_wheels': True,
  },
  'targets': {
    'scripted_ledger_p95_s': 5.0,
    'direct_hard_5of5': True,
    'live_ledger_honest_pass': 'OPEN — Phase 1D gate',
    'host_jobs_per_hour_fast': 12,
  },
}
out = ART / 'performance_benchmark.json'
out.write_text(json.dumps(bench, indent=2), encoding='utf-8')
print('performance_benchmark_written', out)
print(json.dumps({'scripted_s': scripted_s, 'live_s': live_s, 'ratio': ratio, 'direct_mean_s': mean_e}, indent=2))
